1import { useRef, useEffect } from "react";
2
3function Header({ query, onQueryChange }) {
4  const searchRef = useRef(null);
5
6  useEffect(function () {
7    searchRef.current.focus();
8  }, []);
9
10  function handleClear() {
11    onQueryChange("");
12    searchRef.current.focus();
13  }
14
15  return (
16    <header className="header">
17      <h2 className="title-primary">My Daily Journal</h2>
18      <p className="subtitle">Capture your thoughts, one day at a time.</p>
19
20      <input
21        ref={searchRef}
22        className="search-input"
23        type="text"
24        placeholder="Search entries..."
25        value={query}
26        onChange={(e) => onQueryChange(e.target.value)}
27      />
28
29      {query && (
30        <button className="btn-clear" onClick={handleClear}>Clear</button>
31      )}
32
33    </header>
34  );
35}
36
37export default Header;

1import { useRef, useEffect } from "react";
2
3function Drawer({ entry, onClose }) {
4  const drawerRef = useRef(null);
5
6  useEffect(function () {
7    function handleMouseDown(event) {
8      if (drawerRef.current && !drawerRef.current.contains(event.target)) {
9        onClose();
10      }
11    }
12
13    document.addEventListener("mousedown", handleMouseDown);
14    return function () {
15
16      document.removeEventListener("mousedown", handleMouseDown);
17    };
18  }, [onClose]);
19
20  if (!entry) return null;
21
22  return (
23    <div className="drawer-overlay">
24      <div className="drawer" ref={drawerRef}>
25        <button className="drawer-close" onClick={onClose}>×</button>
26        <h2>{entry.title}</h2>
27        <p className="drawer-meta">{entry.date} · {entry.author}</p>
28        <p className="drawer-content">{entry.content}</p>
29      </div>
30    </div>
31  );
32}
33
34export default Drawer;

1import { useState, useEffect } from "react";
2
3function useFetch(url) {
4  const [data, setData] = useState(null);
5  const [isLoading, setIsLoading] = useState(true);
6  const [error, setError] = useState(null);
7
8  useEffect(function () {
9    async function fetchData() {
10      setIsLoading(true);
11      setError(null);
12
13      try {
14        const res = await fetch(url);
15        if (!res.ok) {
16          throw new Error("Could not load data. Status: " + res.status);
17        }
18        const json = await res.json();
19        setData(json);
20        setIsLoading(false);
21      }
22
23      catch (err) {
24        setError(err.message);
25        setIsLoading(false);
26      }
27    }
28
29    fetchData();
30  }, [url]);
31
32  return { data, isLoading, error };
33}
34
35export default useFetch;

1import { useState, useMemo } from "react";
2
3function useSearch(entries) {
4  const [query, setQuery] = useState("");
5
6  const filteredEntries = useMemo(function () {
7    if (!query.trim()) return entries;
8    const lower = query.toLowerCase();
9
10    return entries.filter(function (entry) {
11      return (
12        entry.title.toLowerCase().includes(lower) ||
13        entry.content.toLowerCase().includes(lower)
14      );
15    });
16  }, [entries, query]);
17
18  return { query, setQuery, filteredEntries };
19}
20
21export default useSearch;
